// MEASURE THE REPO STATE. Do not describe it from memory.
//
// WHY THIS EXISTS: `HANDOFF-TO-OZ.md` was written 2026-08-07 and its loudest claim
// -- "NOTHING HAS BEEN COMMITTED SINCE 2026-07-28 ... the largest single risk in
// this repo" -- was still on page one on 2026-08-25, seventeen days after it stopped
// being true. That file's own header says it: "A handoff that is stale is worse than
// no handoff, because it is believed."
//
// So the state block is not typed by anyone. It is measured, and it is regenerated by
// `.githooks/post-commit` on every commit, which is the moment the state changes.
//
// THE RULE THIS FILE FOLLOWS, taken from `assert-tsc-baseline.mjs`:
// a thing it could not measure prints UNMEASURED and names the command that answers
// it. It never prints a default, an empty string, or a guess. A missing measurement
// that looks like a measurement is the defect the whole harness exists to stop.
//
//   node scripts/gen/state.mjs           write the block into docs/STATUS.md
//   node scripts/gen/state.mjs --print   print it, write nothing
import { execFileSync } from "node:child_process"
import { readFileSync, writeFileSync, existsSync, readdirSync, statSync } from "node:fs"
import { fileURLToPath } from "node:url"
import { dirname, join } from "node:path"

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..")
const BEGIN = "<!-- STATE:BEGIN -- generated by scripts/gen/state.mjs. Do not hand-edit. -->"
const END = "<!-- STATE:END -->"

/** Every measurement goes through here. A throw becomes UNMEASURED with the command
 *  that answers it, never a silent fallback. */
const rows = []
function measure(label, fn, answeredBy) {
  try {
    const v = fn()
    if (v === undefined || v === null || v === "") throw new Error("empty result")
    rows.push({ label, value: String(v), ok: true })
  } catch (e) {
    rows.push({
      label,
      value: `UNMEASURED (${e.message.split("\n")[0]}) -- answered by: ${answeredBy}`,
      ok: false,
    })
  }
}
const git = (...a) => execFileSync("git", a, { cwd: ROOT, encoding: "utf8" }).trim()
const countFiles = (rel, filter) =>
  readdirSync(join(ROOT, rel)).filter(filter).length

measure("branch", () => git("rev-parse", "--abbrev-ref", "HEAD"), "git rev-parse --abbrev-ref HEAD")
measure("HEAD", () => `${git("rev-parse", "--short", "HEAD")}  (${git("log", "-1", "--format=%ad", "--date=iso")})`, "git log -1")
measure("HEAD subject", () => git("log", "-1", "--format=%s"), "git log -1 --format=%s")

measure("vs its own origin", () => {
  const up = git("rev-parse", "--abbrev-ref", "@{upstream}")
  const [a, b] = git("rev-list", "--left-right", "--count", `${up}...HEAD`).split(/\s+/)
  return `ahead ${b}, behind ${a}  (${up})`
}, "git rev-list --left-right --count @{upstream}...HEAD")

// The question that actually bit us: is the work reachable from main?
measure("is HEAD on main?", () => {
  const onMain = git("branch", "--contains", "HEAD").split("\n").some((l) => l.replace("*", "").trim() === "main")
  if (onMain) return "YES"
  const behind = git("rev-list", "--count", "HEAD", "^main")
  return `NO -- ${behind} commit(s) on this branch are NOT reachable from main`
}, "git branch --contains HEAD")

measure("working tree", () => {
  const s = git("status", "--porcelain")
  if (!s) return "clean"
  const lines = s.split("\n")
  const untracked = lines.filter((l) => l.startsWith("??")).length
  return `${lines.length} changed path(s), ${untracked} untracked`
}, "git status --porcelain")

measure("stale worktree-agent branches", () => {
  const n = git("branch", "--list", "worktree-agent-*").split("\n").filter(Boolean).length
  return n === 0 ? "none" : `${n} -- do NOT bulk-delete, a dead worktree can hold modified tracked source`
}, "git branch --list 'worktree-agent-*'")

measure("commit identity guard", () => {
  const hp = git("config", "core.hooksPath")
  return existsSync(join(ROOT, hp, "_identity-guard.sh")) ? `ON (core.hooksPath=${hp})` : `hooksPath=${hp} but no _identity-guard.sh`
}, "git config core.hooksPath")

measure("gates (scripts/verify/assert-*)", () => countFiles("scripts/verify", (f) => f.startsWith("assert-") && f.endsWith(".mjs")), "ls scripts/verify")
measure("probes (scripts/verify/_probe-*)", () => countFiles("scripts/verify", (f) => f.startsWith("_probe-") && f.endsWith(".mjs")), "ls scripts/verify")
measure("explainers", () => {
  const ns = readdirSync(join(ROOT, "docs/explainers"))
    .map((f) => /^(\d+)-/.exec(f)?.[1]).filter(Boolean).map(Number).sort((a, b) => a - b)
  const gaps = []
  for (let i = ns[0]; i < ns[ns.length - 1]; i++) if (!ns.includes(i)) gaps.push(i)
  return `${ns.length} files, ${ns[0]}-${ns[ns.length - 1]}. GAPS (DO NOT REUSE): ${gaps.join(", ") || "none"}. Next free: ${ns[ns.length - 1] + 1}`
}, "ls docs/explainers")

measure("dev server :3105", () => {
  try {
    execFileSync("lsof", ["-nP", "-iTCP:3105", "-sTCP:LISTEN"], { encoding: "utf8" })
    return "UP"
  } catch { return "DOWN -- node ./node_modules/.bin/next dev --webpack -p 3105" }
}, "lsof -nP -iTCP:3105 -sTCP:LISTEN")

// tsc is too slow for a commit hook. Report the LAST recorded run and how old it is,
// and never imply it was taken now.
// `--record-tsc` RUNS the gate and stores its verdict, so the line in the block is a real
// run and never a hand-typed one. The commit hook does not do this: tsc takes minutes and a
// hook that slow gets disabled, and a disabled hook measures nothing at all.
if (process.argv.includes("--record-tsc")) {
  let out = "", code = 0
  try {
    out = execFileSync("node", ["scripts/verify/assert-tsc-baseline.mjs"], { cwd: ROOT, encoding: "utf8" })
  } catch (e) { out = (e.stdout || "") + (e.stderr || ""); code = e.status ?? 1 }
  const pass = (out.match(/^PASS/gm) || []).length
  const fail = (out.match(/^FAIL/gm) || []).length
  const unswept = (out.match(/^UNSWEPT/gm) || []).length
  const verdict = `${pass} PASS · ${fail} FAIL · ${unswept} UNSWEPT · exit ${code}` +
    (code === 3 ? " (PARTIAL — a channel was never reached, which is NOT a pass)" : "")
  writeFileSync(join(ROOT, "docs/verification/.tsc-baseline-last.json"),
    JSON.stringify({ at: new Date().toISOString(), result: verdict, exit: code }, null, 2))
  console.log(`recorded: ${verdict}`)
}

measure("tsc baseline", () => {
  const p = join(ROOT, "docs/verification/.tsc-baseline-last.json")
  if (!existsSync(p)) throw new Error("never recorded here")
  const j = JSON.parse(readFileSync(p, "utf8"))
  const ageH = Math.round((Date.now() - Date.parse(j.at)) / 36e5)
  return `${j.result} -- as recorded ${j.at} (${ageH}h ago), NOT re-run by this hook`
}, "node scripts/verify/assert-tsc-baseline.mjs")

measure("engine file sizes", () => {
  const files = ["components/viewport-3d.tsx", "lib/hero-motion.ts", "lib/style-fusion.ts",
    "lib/pen-reveal.ts", "lib/stroke-schedule.ts", "lib/geometry-engines.ts"]
  return files.filter((f) => existsSync(join(ROOT, f)))
    .map((f) => `${f} ${(statSync(join(ROOT, f)).size / 1024).toFixed(0)}K`).join(" · ")
}, "ls -la on the engine files")

const stamp = git("log", "-1", "--format=%cI")
const block = [
  BEGIN,
  "",
  "```",
  ...rows.map((r) => `${r.label.padEnd(32)}${r.value}`),
  "```",
  "",
  `_Measured from disk at commit \`${git("rev-parse", "--short", "HEAD")}\` (${stamp}) by \`scripts/gen/state.mjs\`,`,
  `run from \`.githooks/post-commit\`. Nothing in this block is typed by hand._`,
  ...(rows.some((r) => !r.ok)
    ? ["", `⚠️ **${rows.filter((r) => !r.ok).length} row(s) came back UNMEASURED.** That is not a pass and not a failure. Nothing was measured; run the command each names.`]
    : []),
  END,
].join("\n")

if (process.argv.includes("--print")) { console.log(block); process.exit(0) }

const target = join(ROOT, "docs/STATUS.md")
if (!existsSync(target)) { console.error(`no docs/STATUS.md to write into`); process.exit(1) }
const cur = readFileSync(target, "utf8")
const i = cur.indexOf(BEGIN), j = cur.indexOf(END)
if (i === -1 || j === -1) {
  console.error(`docs/STATUS.md has no STATE:BEGIN/STATE:END markers -- refusing to guess where the block goes`)
  process.exit(1)
}
writeFileSync(target, cur.slice(0, i) + block + cur.slice(j + END.length))
console.log(`state.mjs: wrote ${rows.length} rows into docs/STATUS.md (${rows.filter((r) => !r.ok).length} UNMEASURED)`)
